  f jsonb; st jsonb; v_flow uuid; v_prev uuid; v_id uuid; i int;
BEGIN
  FOR f IN SELECT * FROM jsonb_array_elements(v_plan) LOOP
    DELETE FROM public.flow_steps WHERE flow_id IN (SELECT id FROM public.flows WHERE user_id=v_user AND name = f->>'name');
    DELETE FROM public.flows WHERE user_id=v_user AND name = f->>'name';
    INSERT INTO public.flows (name, description, user_id, flow_kind, active, delay_min_seconds, delay_max_seconds)
      VALUES (f->>'name', f->>'description', v_user, 'whatsapp', false, 5, 15) RETURNING id INTO v_flow;
    v_prev := NULL; i := 0;
    FOR st IN SELECT * FROM jsonb_array_elements(f->'steps') LOOP
      v_id := gen_random_uuid();
      INSERT INTO public.flow_steps (id, flow_id, step_order, step_type, custom_message, delay_minutes, parent_step_id, is_entry,
        delay_min_seconds, delay_max_seconds, media_url, media_type, file_name, timeout_minutes)
      VALUES (v_id, v_flow, i, st->>'t', st->>'msg', 0, v_prev, i = 0,
        (st->>'d')::int, CASE WHEN st->>'d' IS NULL THEN NULL ELSE (st->>'d')::int + 3 END,
        st->>'url', st->>'mtype', st->>'fname', (st->>'timeout')::int);
      v_prev := v_id; i := i + 1;
    END LOOP;
